var BOX=null,HIS=[],CUR=null;function CLOSE(){if(BOX){BOX.remove();BOX=null;HIS=[];CUR=null}}
function ESC(s){return String(s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function INL(s){return ESC(s).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\[\[([kc]):([^|\]]+)\|([^\]]+)\]\]/g,function(m,t,v,l){return(t=='c'&&!(window.GOCHAP&&window.GOCHAP[v]))?'<b>'+l+'</b>':'<a href="#" data-'+t+'="'+v+'">'+l+'</a>'})}
function R(t){return String(t).split(/\n\s*\n/).map(function(b){var L=b.split('\n'),o='';if(/^## /.test(L[0])){o='<h4>'+INL(L[0].slice(3))+'</h4>';L=L.slice(1)}if(!L.length)return o;if(L.every(function(x){return/^- /.test(x)}))return o+'<ul>'+L.map(function(x){return'<li>'+INL(x.slice(2))+'</li>'}).join('')+'</ul>';var i=L.findIndex(function(x){return/^- /.test(x)});if(i>0&&L.slice(i).every(function(x){return/^- /.test(x)}))return o+'<p>'+INL(L.slice(0,i).join(' '))+'</p><ul>'+L.slice(i).map(function(x){return'<li>'+INL(x.slice(2))+'</li>'}).join('')+'</ul>';return o+'<p>'+INL(L.join(' '))+'</p>'}).join('')}
var CSS='.gohelp{position:absolute;z-index:2147483000;background:#fff;color:#111;border:2.5px solid #000;border-radius:10px;width:min(460px,calc(100vw - 16px));max-height:min(72vh,520px);display:flex;flex-direction:column;box-shadow:0 10px 28px rgba(0,0,0,.3);font:14px/1.55 system-ui,-apple-system,"Segoe UI",Arial,sans-serif;text-align:left;white-space:normal;overflow:hidden}'
